#!/usr/bin/env bash
# Regenerates the vendored TypeScript checker inputs of code mode's `run_code`:
#   typescript.js.zst   typescript/lib/typescript.js (the compiler, run in its own V8 isolate)
#   libs.json.zst       {"lib.es5.d.ts": "...", ...}: the lib files reachable from lib.es2024.d.ts
#   ts-blank-space.js   ts-blank-space's out/*.js as one classic script on the global `ts`
#   LICENSE-typescript.txt, ThirdPartyNoticeText-typescript.txt, LICENSE-ts-blank-space.txt
#
# Fetches the pinned versions with `npm pack` and checks each tarball against
# its pinned npm sha512 integrity. Needs npm, python3 and zstd. Set
# NPM_REGISTRY to use a mirror (e.g. https://registry.npmmirror.com).
set -euo pipefail

TYPESCRIPT_VERSION=6.0.3
TYPESCRIPT_INTEGRITY=sha512-y2TvuxSZPDyQakkFRPZHKFm+KKVqIisdg9/CZwm9ftvKXLP8NRWj38/ODjNbr43SsoXqNuAisEf1GdCxqWcdBw==
BLANK_SPACE_VERSION=0.9.0
BLANK_SPACE_INTEGRITY=sha512-TU6coIZm6RxGgAjroRKmi6aCQ7Pq7cT+1I+bTKBepD6joOuWqUCOptVlz+eurqTnatnQOimlR8XB5sQZ6ULwbw==

out_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
work_dir="$(mktemp -d)"
trap 'rm -rf "$work_dir"' EXIT

registry_args=()
if [[ -n "${NPM_REGISTRY:-}" ]]; then
  registry_args=(--registry "$NPM_REGISTRY")
fi

fetch() {
  local name="$1" version="$2" integrity="$3"
  (cd "$work_dir" && npm pack --silent "${registry_args[@]}" "$name@$version" >/dev/null)
  local tarball="$work_dir/$name-$version.tgz"
  local actual
  actual="sha512-$(python3 -c 'import base64,hashlib,sys; print(base64.b64encode(hashlib.sha512(open(sys.argv[1],"rb").read()).digest()).decode())' "$tarball")"
  if [[ "$actual" != "$integrity" ]]; then
    echo "integrity mismatch for $name@$version: $actual" >&2
    exit 1
  fi
  mkdir -p "$work_dir/$name"
  tar -xzf "$tarball" -C "$work_dir/$name" --strip-components=1
}

fetch typescript "$TYPESCRIPT_VERSION" "$TYPESCRIPT_INTEGRITY"
fetch ts-blank-space "$BLANK_SPACE_VERSION" "$BLANK_SPACE_INTEGRITY"

zstd -q -19 -f "$work_dir/typescript/lib/typescript.js" -o "$out_dir/typescript.js.zst"

python3 - "$work_dir/typescript/lib" "$work_dir/libs.json" <<'PY'
import json, re, sys
from pathlib import Path

lib_dir, out = Path(sys.argv[1]), Path(sys.argv[2])
reference = re.compile(r'^/// <reference lib="([^"]+)" />', re.M)
libs, pending = {}, ["es2024"]
while pending:
    name = f"lib.{pending.pop()}.d.ts"
    if name in libs:
        continue
    text = (lib_dir / name).read_text(encoding="utf-8")
    libs[name] = text
    pending.extend(reference.findall(text))
for forbidden in ("lib.dom.d.ts", "lib.webworker.d.ts"):
    assert forbidden not in libs, forbidden
out.write_text(json.dumps(dict(sorted(libs.items())), ensure_ascii=False), encoding="utf-8")
print(f"{len(libs)} lib files", file=sys.stderr)
PY
zstd -q -19 -f "$work_dir/libs.json" -o "$out_dir/libs.json.zst"

python3 - "$work_dir/ts-blank-space/out" "$out_dir/ts-blank-space.js" "$BLANK_SPACE_VERSION" <<'PY'
import sys
from pathlib import Path

src, out, version = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]

def replace_once(text, old, new):
    assert text.count(old) == 1, f"expected one {old!r}"
    return text.replace(old, new)

blank_string = (src / "blank-string.js").read_text(encoding="utf-8")
blank_string = replace_once(blank_string, "export default class BlankString", "class BlankString")
index = (src / "index.js").read_text(encoding="utf-8")
index = replace_once(index, 'import tslib from "typescript";', "const tslib = globalThis.ts;")
index = replace_once(index, 'import BlankString from "./blank-string.js";', "")
index = replace_once(index, "export default function tsBlankSpace(", "function tsBlankSpace(")
index = replace_once(index, "export function blankSourceFile(", "function blankSourceFile(")
assert "import " not in "\n".join(l for l in index.splitlines() if l.startswith("import")), "unexpected import"
out.write_text(
    f"// ts-blank-space {version} (Apache-2.0, https://github.com/bloomberg/ts-blank-space),\n"
    "// out/blank-string.js and out/index.js joined into one classic script that uses\n"
    "// the global `ts` and defines `globalThis.tsBlankSpace`. Generated by update.sh.\n"
    "globalThis.tsBlankSpace = (() => {\n"
    f"{blank_string}\n{index}\n"
    "return { tsBlankSpace, blankSourceFile };\n"
    "})();\n",
    encoding="utf-8",
)
PY

cp "$work_dir/typescript/LICENSE.txt" "$out_dir/LICENSE-typescript.txt"
cp "$work_dir/typescript/ThirdPartyNoticeText.txt" "$out_dir/ThirdPartyNoticeText-typescript.txt"
cp "$work_dir/ts-blank-space/LICENSE" "$out_dir/LICENSE-ts-blank-space.txt"
printf 'typescript %s\nts-blank-space %s\n' "$TYPESCRIPT_VERSION" "$BLANK_SPACE_VERSION" >"$out_dir/VERSIONS"
echo "updated $out_dir" >&2
